extends Node3D
class_name CrowdStream

signal infrastructure_warning(target_id: String, enemy_uid: int)
signal infrastructure_strike(target_id: String, damage: float, enemy_uid: int)
## Host-authoritative packed enemy crowd, wire format = HSNP v1 (uid-addressed).
##
## VS2-T5: single crowd codec project-wide (EnemySnapshotCodec); core_hp moved
## out of the snapshot to a reliable synced var (CoreObject StateSynchronizer).
## VS2-T2: client render buffer is sized by the DECODED snapshot, so host/client
## enemy-count config mismatches cannot cause index errors; hostile counts are
## clamped in the codec. Dead enemies use state 2 per CrowdSim canon.
## VS2-T3: interpolation respects the 100 ms buffer (no dead condition) and
## carries full per-snapshot state arrays (dead enemies are hidden).

const SNAPSHOT_EVERY_TICKS := 2   # 30 Hz tick -> 15 Hz snapshots
const LADDER_FILL_SEC := 8.0       # pure stress ladder reaches target before measurement
const INTERP_DELAY_MS := 100.0
const ARENA_SIZE_M := 48.0
# Keep each unreliable RPC comfortably below ENet's 1392-byte MTU after
# Godot RPC/Variant framing. Full HSNP snapshots are reassembled client-side.
const SNAPSHOT_RPC_PAYLOAD_MAX := 1100
const MAX_SNAPSHOT_CHUNKS := 64

@export var count := 64

# Host sim arrays (SoA), uid-addressed on the wire
var _uid := PackedInt32Array()
var _xs := PackedFloat32Array()
var _zs := PackedFloat32Array()
var _hp := PackedFloat32Array()
var _state := PackedInt32Array()
var _flags := PackedInt32Array()
var _lane := PackedInt32Array()
var _respawn_t := PackedFloat32Array()
var _next_uid := 0
var _spawned_uids := PackedInt32Array()
var _died_uids := PackedInt32Array()

var _tick := 0
var core: CoreObject = null   # authoritative core HP lives there (VS2-T5)

# client-side: last decoded snapshot + interp history
var _snaps := []   # [{recv_ms:int, uid,x,z,state,hp (decoded arrays)}]

var _role_mms: Dictionary = {}
var _armored_weak_mm: MultiMesh = null
var _metrics = null
var ladder_print := false
var _last_snap_bytes := 0
## Этап 4 remainder: when enabled, the HOST simulation is a real CrowdSim
## (flow field + damage(uid)); snapshots are encoded straight from SoA.
var sim_mode := false
var sim: CrowdSim = null
var _sim_acc := 0.0
var _last_core_hp := -1.0
var _core_damage_debt := 0.0
var _lane_c_open := false
var _rendered_count := 0
var _snapshot_tx_seq := 0
var _snapshot_rx_seq := -1
var _snapshot_rx_total := 0
var _snapshot_rx_received := 0
var _snapshot_rx_chunks: Array = []
var _host_elapsed_sec := 0.0


func setup(p_count: int, p_metrics) -> void:
	count = p_count
	_metrics = p_metrics


## Этап 4 remainder: back the host crowd with CrowdSim (flow-field nav,
## trickle spawn, damage(uid)). Client decode/interp path is unchanged.
func enable_sim(seed_v: int, initial_fill: bool = true) -> void:
	sim_mode = true
	var field := OperationNav.build_field(false)
	sim = CrowdSim.new(
		count,
		seed_v,
		OperationLayout.GRID_W,
		OperationLayout.GRID_H,
		OperationLayout.CROWD_CELL
	)
	sim.configure_navigation(field, OperationNav.core_cell(), OperationNav.lane_cells(false))
	_last_core_hp = sim.core_hp
	_core_damage_debt = 0.0
	if initial_fill:
		# Capacity ladder measures steady-state crowd/network behavior, not
		# authored operation spawn cadence. Keep the fill window bounded so
		# 64/96/128/150 reach their requested population before timeout.
		sim.begin_wave(count, LADDER_FILL_SEC)


func set_lane_c_open(open: bool) -> void:
	if not sim_mode or sim == null or open == _lane_c_open:
		return
	_lane_c_open = open
	sim.configure_navigation(
		OperationNav.build_field(open),
		OperationNav.core_cell(),
		OperationNav.lane_cells(open)
	)


func configure_role_tuning(roles: Dictionary) -> void:
	if sim_mode and sim != null:
		sim.configure_role_tuning(roles)


func configure_infrastructure_targets(world_targets: Array) -> void:
	if not sim_mode or sim == null:
		return
	var half := sim.field.size_m * 0.5
	var field_targets: Array = []
	for target in world_targets:
		var pos: Vector3 = target.get("pos", Vector3.ZERO)
		field_targets.append({
			"id": str(target.get("id", "")),
			"pos": Vector2(pos.x + half, pos.z + half),
			"active": bool(target.get("active", true)),
		})
	sim.configure_infrastructure_targets(field_targets)


func disable_infrastructure_target(target_id: String) -> void:
	if sim_mode and sim != null:
		sim.disable_infrastructure_target(target_id)


func queue_spawn_intent(lane_id: String, role_name: String, amount: int,
		aggression: float = 1.0, batch_token: int = 0) -> bool:
	if not sim_mode or sim == null or amount <= 0:
		return false
	var lane_index: int = int({"A": 0, "B": 1, "C": 2}.get(lane_id, -1))
	if lane_index < 0:
		return false
	if lane_id == "C" and not _lane_c_open:
		set_lane_c_open(true)
	var duration := clampf(2.5 / maxf(aggression, 0.25), 0.5, 4.0)
	sim.queue_batch(amount, lane_index, duration, CrowdSim.role_id(role_name), batch_token)
	return true


func batch_present(batch_token: int) -> bool:
	return sim_mode and sim != null and sim.batch_present(batch_token)


func simulation_idle() -> bool:
	if sim_mode and sim != null:
		return sim.active == 0 and sim.spawn_idle()
	return false


func _ingest_snapshot(bytes: PackedByteArray, inbound: bool = true) -> void:
	var snap := EnemySnapshotCodec.decode(bytes)
	if snap.is_empty():
		if _metrics:
			_metrics.count("crowd_snap_rejected")
		return
	if _metrics and inbound:
		_metrics.add_bytes("crowd_in", bytes.size())
		_metrics.count("crowd_snaps_recv")
	var half: float = snap.arena_size_m * 0.5
	var wx: PackedFloat32Array = snap.x
	var wz: PackedFloat32Array = snap.z
	for i in wx.size():
		wx[i] = wx[i] - half
		wz[i] = wz[i] - half
	_snaps.append({
		"recv_ms": Time.get_ticks_msec(), "uid": snap.uid,
		"x": wx, "z": wz, "state": snap.state, "hp": snap.hp,
		"flags": snap.flags, "lane": snap.lane,
	})
	while _snaps.size() > 6:
		_snaps.pop_front()


func _ready() -> void:
	_build_view()
	if multiplayer.is_server() and not sim_mode:
		_init_enemies()


func _build_view() -> void:
	# Fixed batched role buckets: distinct silhouettes without Node-per-enemy.
	_role_mms.clear()

	var pressure := CapsuleMesh.new()
	pressure.radius = 0.32
	pressure.height = 1.05
	_role_mms["PRESSURE"] = _create_role_bucket(
		"CrowdPressure", pressure, Color(0.78, 0.20, 0.12), false)

	var armored := BoxMesh.new()
	armored.size = Vector3(1.15, 1.55, 0.92)
	_role_mms["ARMORED"] = _create_role_bucket(
		"CrowdArmored", armored, Color(0.10, 0.11, 0.12), false)

	var harasser := CylinderMesh.new()
	harasser.top_radius = 0.62
	harasser.bottom_radius = 0.62
	harasser.height = 0.28
	harasser.radial_segments = 6
	_role_mms["HARASSER"] = _create_role_bucket(
		"CrowdHarasser", harasser, Color(0.52, 0.22, 0.62), true)

	var weak := SphereMesh.new()
	weak.radius = 0.20
	weak.height = 0.40
	_armored_weak_mm = _create_role_bucket(
		"ArmoredWeakpoints", weak, Color(1.0, 0.55, 0.12), true)


func _create_role_bucket(name_v: String, mesh: Mesh, color: Color,
		emissive: bool) -> MultiMesh:
	var inst := MultiMeshInstance3D.new()
	inst.name = name_v
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.mesh = mesh
	mm.instance_count = maxi(1, count)
	mm.visible_instance_count = 0
	var mat := StandardMaterial3D.new()
	mat.albedo_color = color
	mat.roughness = 0.78
	if emissive:
		mat.emission_enabled = true
		mat.emission = color
		mat.emission_energy_multiplier = 1.7
	inst.material_override = mat
	inst.multimesh = mm
	add_child(inst)
	return mm


func _init_enemies() -> void:
	_uid.resize(count)
	_xs.resize(count)
	_zs.resize(count)
	_hp.resize(count)
	_state.resize(count)
	_flags.resize(count)
	_lane.resize(count)
	_respawn_t.resize(count)
	for i in count:
		_uid[i] = _next_uid
		_next_uid += 1
		var ang := TAU * float(i) / float(count)
		_xs[i] = cos(ang) * 16.0
		_zs[i] = sin(ang) * 16.0
		_hp[i] = 100.0
		_state[i] = EnemySnapshotCodec.ST_MOVE
		_flags[i] = 0
		_lane[i] = 0


func enemy_count() -> int:
	if multiplayer.is_server() and sim_mode and sim != null:
		return sim.active
	return count if multiplayer.is_server() else _decoded_count()


func _decoded_count() -> int:
	return 0 if _snaps.is_empty() else _snaps[-1].uid.size()


## Host-only simulation step, called from boot on NetworkTime.after_tick.
func host_step(dt: float) -> void:
	_host_elapsed_sec += dt
	if sim_mode:
		# Этап 4 remainder: real CrowdSim drives the host crowd. Fixed 60 Hz
		# sim steps accumulated from the net tick delta; snapshots encoded
		# straight from SoA; core erosion bridged to the CoreObject.
		_sim_acc += dt
		var sdt := 1.0 / 60.0
		while _sim_acc >= sdt:
			sim.step(sdt)
			_sim_acc -= sdt
		_tick += 1
		if _tick % SNAPSHOT_EVERY_TICKS == 0:
			var bytes := EnemySnapshotCodec.encode(sim, _tick)
			_last_snap_bytes = bytes.size()
			# The authority renders straight from CrowdSim. Decoding our own HSNP
			# only created a delayed mirror and made visible targets trail hit truth.
			_send_snapshot(bytes)
			EnemySnapshotCodec.clear_events(sim)
			if ladder_print and _tick % 120 == 0:
				print("[CROWDSTAT] t=%.1f alive=%d snap_bytes=%d" % [
					_host_elapsed_sec, sim.active, _last_snap_bytes])
		for warning in sim.take_infrastructure_warnings():
			infrastructure_warning.emit(
				str(warning.get("target_id", "")),
				int(warning.get("uid", 0)))
		for strike in sim.take_infrastructure_strikes():
			infrastructure_strike.emit(
				str(strike.get("target_id", "")),
				float(strike.get("damage", 0.0)),
				int(strike.get("uid", 0)))
		if core != null:
			var dh := _last_core_hp - sim.core_hp
			if _last_core_hp >= 0.0 and dh > 0.0:
				var consumed := consume_fractional_damage(_core_damage_debt, dh)
				_core_damage_debt = float(consumed.debt)
				var whole := int(consumed.whole)
				if whole > 0:
					core.apply_core_damage(whole)
			_last_core_hp = sim.core_hp
		return
	if _uid.is_empty():
		return
	_tick += 1
	_spawned_uids.clear()
	_died_uids.clear()
	for i in count:
		if _state[i] == EnemySnapshotCodec.ST_DEAD:
			_respawn_t[i] -= dt
			if _respawn_t[i] <= 0.0:
				var ang := randf() * TAU
				_xs[i] = cos(ang) * 16.0
				_zs[i] = sin(ang) * 16.0
				_hp[i] = 100.0
				_state[i] = EnemySnapshotCodec.ST_MOVE
				_uid[i] = _next_uid            # new identity after respawn
				_next_uid += 1
				_spawned_uids.append(_uid[i])
			continue
		var dir := Vector3(CORE_POS_X - _xs[i], 0, CORE_POS_Z - _zs[i]).normalized()
		_xs[i] += dir.x * 2.5 * dt
		_zs[i] += dir.z * 2.5 * dt
		if Vector3(_xs[i], 0, _zs[i]).distance_to(CORE_POS) < 2.0 and core:
			core.apply_core_damage(int(ceil(20.0 * dt)))
	if _tick % SNAPSHOT_EVERY_TICKS == 0:
		_broadcast_snapshot()


const CORE_POS := Vector3.ZERO
const CORE_POS_X := 0.0
const CORE_POS_Z := 0.0


## HSNP v1 quantizes positions over [0, arena_size_m]; this lab's world is
## centered at origin, so we shift by ARENA_SIZE_M/2 at the wire boundary.
static func _to_wire(v: float) -> float:
	return clampf(v + ARENA_SIZE_M * 0.5, 0.0, ARENA_SIZE_M)


static func _from_wire(v: float) -> float:
	return v - ARENA_SIZE_M * 0.5


func _broadcast_snapshot() -> void:
	var wx := PackedFloat32Array(); wx.resize(count)
	var wz := PackedFloat32Array(); wz.resize(count)
	for i in count:
		wx[i] = _to_wire(_xs[i])
		wz[i] = _to_wire(_zs[i])
	var bytes := EnemySnapshotCodec.encode_dict({
		"tick": _tick,
		"arena_size_m": ARENA_SIZE_M,
		"uid": _uid, "x": wx, "z": wz,
		"hp": _hp, "state": _state, "flags": _flags, "lane": _lane,
		"spawned": _spawned_uids, "died": _died_uids,
	})
	_last_snap_bytes = bytes.size()
	_send_snapshot(bytes)
	if ladder_print and _tick % 120 == 0:
		var alive_n := 0
		for k in count:
			if _state[k] != EnemySnapshotCodec.ST_DEAD:
				alive_n += 1
		print("[CROWDSTAT] t=%.1f alive=%d snap_bytes=%d" % [
			_host_elapsed_sec, alive_n, _last_snap_bytes])


static func consume_fractional_damage(debt: float, delta: float) -> Dictionary:
	var total := maxf(0.0, debt) + maxf(0.0, delta)
	var whole := int(floor(total + 0.000001))
	return {"whole": whole, "debt": total - float(whole)}


func metrics_enabled() -> bool:
	return _metrics != null


static func split_snapshot_bytes(bytes: PackedByteArray,
		max_payload: int = SNAPSHOT_RPC_PAYLOAD_MAX) -> Array:
	var chunks: Array = []
	if bytes.is_empty() or max_payload <= 0:
		return chunks
	var offset := 0
	while offset < bytes.size():
		var end := mini(offset + max_payload, bytes.size())
		chunks.append(bytes.slice(offset, end))
		offset = end
	return chunks


static func join_snapshot_chunks(chunks: Array) -> PackedByteArray:
	var bytes := PackedByteArray()
	for chunk_v in chunks:
		if not chunk_v is PackedByteArray:
			return PackedByteArray()
		bytes.append_array(chunk_v as PackedByteArray)
	return bytes


func _send_snapshot(bytes: PackedByteArray) -> void:
	if _metrics:
		_metrics.add_bytes("crowd_out", bytes.size())
		_metrics.count("crowd_snaps_sent")
	var chunks := split_snapshot_bytes(bytes)
	if chunks.is_empty() or chunks.size() > MAX_SNAPSHOT_CHUNKS:
		if _metrics:
			_metrics.count("crowd_snap_rejected_oversize")
		push_error("crowd snapshot requires %d chunks; max is %d" % [
			chunks.size(), MAX_SNAPSHOT_CHUNKS])
		return
	# Sequence every snapshot, including one-chunk frames. This prevents an old
	# incomplete multi-chunk snapshot from completing after a newer small frame.
	_snapshot_tx_seq += 1
	for i in range(chunks.size()):
		crowd_snapshot_chunk.rpc(_snapshot_tx_seq, i, chunks.size(), chunks[i])
	if _metrics:
		_metrics.count("crowd_chunks_sent", chunks.size())
		if chunks.size() > 1:
			_metrics.count("crowd_snap_chunked")


func _begin_snapshot_reassembly(seq: int, total: int) -> void:
	_snapshot_rx_seq = seq
	_snapshot_rx_total = total
	_snapshot_rx_received = 0
	_snapshot_rx_chunks.clear()
	for _i in range(total):
		_snapshot_rx_chunks.append(PackedByteArray())


@rpc("any_peer", "call_remote", "unreliable_ordered")
func crowd_snapshot_chunk(seq: int, chunk_index: int, total: int,
		chunk: PackedByteArray) -> void:
	if multiplayer.get_remote_sender_id() != 1:
		return
	if total <= 0 or total > MAX_SNAPSHOT_CHUNKS or chunk_index < 0 \
			or chunk_index >= total or chunk.size() > SNAPSHOT_RPC_PAYLOAD_MAX:
		if _metrics:
			_metrics.count("crowd_snap_chunk_rejected")
		return
	if seq < _snapshot_rx_seq:
		return
	if seq != _snapshot_rx_seq:
		_begin_snapshot_reassembly(seq, total)
	elif total != _snapshot_rx_total:
		return
	if (_snapshot_rx_chunks[chunk_index] as PackedByteArray).is_empty():
		_snapshot_rx_received += 1
	_snapshot_rx_chunks[chunk_index] = chunk
	if _snapshot_rx_received != _snapshot_rx_total:
		return
	var bytes := join_snapshot_chunks(_snapshot_rx_chunks)
	_snapshot_rx_total = 0
	_snapshot_rx_received = 0
	_snapshot_rx_chunks.clear()
	_ingest_snapshot(bytes, true)


@rpc("any_peer", "call_remote", "unreliable_ordered")
func crowd_snapshot(bytes: PackedByteArray) -> void:
	if multiplayer.get_remote_sender_id() != 1:
		return
	_ingest_snapshot(bytes, true)


func _active_session() -> bool:
	var p := multiplayer.multiplayer_peer
	return p != null and p.get_connection_status() == MultiplayerPeer.CONNECTION_CONNECTED


func _process(_delta: float) -> void:
	if multiplayer.is_server():
		if sim_mode and sim != null:
			_render_authoritative_sim()
		else:
			_render_arrays(_xs, _zs, _state, _flags)
		return
	if _snaps.is_empty():
		return
	var newest: Dictionary = _snaps[_snaps.size() - 1]
	if _snaps.size() == 1:
		_render_arrays(newest.x, newest.z, newest.state,
			newest.get("flags", PackedByteArray()))
		return
	var older: Dictionary = _snaps[_snaps.size() - 2]
	var sampled := CrowdInterp.sample_interp(
		older, newest, Time.get_ticks_msec(), INTERP_DELAY_MS)
	if sampled.is_empty():
		_render_arrays(newest.x, newest.z, newest.state,
			newest.get("flags", PackedByteArray()))
	else:
		_render_arrays(sampled.x, sampled.z, sampled.state,
			sampled.get("flags", PackedByteArray()))


func _ensure_render_capacity(required: int) -> void:
	for mm_v in _role_mms.values():
		var mm := mm_v as MultiMesh
		if mm != null and required > mm.instance_count:
			mm.instance_count = required
	if _armored_weak_mm != null and required > _armored_weak_mm.instance_count:
		_armored_weak_mm.instance_count = required


func _role_from_flags(flags_v: int) -> String:
	if (flags_v & CrowdSim.F_ROLE_ARMORED) != 0:
		return "ARMORED"
	if (flags_v & CrowdSim.F_ROLE_HARASSER) != 0:
		return "HARASSER"
	return "PRESSURE"


func _render_authoritative_sim() -> void:
	if sim == null:
		return
	# CrowdSim stores positions in field coordinates while the authored world is
	# centered on the origin. Use the same conversion as enemy_position(), so
	# the host's visible MultiMeshes and host-authoritative hit tests share truth.
	var half := sim.field.size_m * 0.5
	_render_arrays(sim.px, sim.pz, sim.state, sim.flags, Vector2(-half, -half))


func _render_arrays(xs, zs, states, role_flags = PackedByteArray(),
		world_offset: Vector2 = Vector2.ZERO) -> void:
	var n := mini(xs.size(), mini(zs.size(), states.size()))
	_ensure_render_capacity(n)
	var counts := {"PRESSURE": 0, "ARMORED": 0, "HARASSER": 0}
	var weak_count := 0
	var now := float(Time.get_ticks_msec()) * 0.004

	for i in n:
		if states[i] == EnemySnapshotCodec.ST_DEAD:
			continue
		var flags_v := int(role_flags[i]) if i < role_flags.size() else 0
		var role := _role_from_flags(flags_v)
		var mm := _role_mms.get(role) as MultiMesh
		if mm == null:
			continue
		var slot := int(counts[role])
		counts[role] = slot + 1

		var pos := Vector3(
			float(xs[i]) + world_offset.x, 0.54,
			float(zs[i]) + world_offset.y)
		var basis := Basis.IDENTITY
		match role:
			"ARMORED":
				pos.y = 0.78
			"HARASSER":
				pos.y = 2.35 + sin(now + float(i) * 0.73) * 0.14
				basis = Basis.IDENTITY.scaled(Vector3(1.45, 1.0, 0.76))
			_:
				pass
		mm.set_instance_transform(slot, Transform3D(basis, pos))

		if role == "ARMORED" and _armored_weak_mm != null:
			_armored_weak_mm.set_instance_transform(
				weak_count,
				Transform3D(Basis.IDENTITY, Vector3(pos.x, 1.47, pos.z)))
			weak_count += 1

	for role in counts:
		var mm := _role_mms.get(role) as MultiMesh
		if mm != null:
			mm.visible_instance_count = int(counts[role])
	if _armored_weak_mm != null:
		_armored_weak_mm.visible_instance_count = weak_count
	_rendered_count = n


func enemy_position(i: int) -> Vector3:
	# Authority-side hit test reads the active backend; clients never resolve hits.
	if sim_mode and sim != null:
		if i < 0 or i >= sim.active:
			return Vector3.ZERO
		var half := sim.field.size_m * 0.5
		var y := 2.2 if sim.role_of_slot(i) == CrowdSim.ROLE_HARASSER else 0.5
		return Vector3(sim.px[i] - half, y, sim.pz[i] - half)
	if i < 0 or i >= _xs.size():
		return Vector3.ZERO
	return Vector3(_xs[i], 0.5, _zs[i])


func enemy_role(i: int) -> String:
	if sim_mode and sim != null and i >= 0 and i < sim.active:
		return CrowdSim.role_name(sim.role_of_slot(i))
	return "PRESSURE"


func world_los_clear(from: Vector3, to: Vector3, collision_mask: int = 1,
		exclude: Array[RID] = []) -> bool:
	if not is_inside_tree():
		return true
	var q := PhysicsRayQueryParameters3D.create(from, to, collision_mask, exclude)
	q.collide_with_areas = false
	q.collide_with_bodies = true
	return get_world_3d().direct_space_state.intersect_ray(q).is_empty()


func find_enemy_in_cone_los(origin: Vector3, forward: Vector3, max_range: float,
		min_dot: float = 0.94, exclude: Array[RID] = []) -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return -1
	var best := -1
	var best_d := max_range
	var flat_fwd := Vector3(forward.x, 0.0, forward.z).normalized()
	for i in range(sim.active):
		var target := enemy_position(i)
		var to_enemy := target - origin
		var flat := Vector3(to_enemy.x, 0.0, to_enemy.z)
		var d := flat.length()
		if d <= 0.001 or d >= best_d:
			continue
		if flat_fwd.dot(flat / d) < min_dot:
			continue
		if not world_los_clear(origin, target + Vector3.UP * 0.25, 1, exclude):
			continue
		best = i
		best_d = d
	return best


## Host-authoritative camera-ray resolver for the packed crowd.
## Crowd agents deliberately stay data-only; this performs cheap ray-vs-role
## proxy tests after clamping the ray at the first world collision.
func raycast_enemy(origin: Vector3, direction: Vector3, max_range: float,
		exclude: Array[RID] = []) -> Dictionary:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return {"index": -1, "end": origin + direction.normalized() * max_range,
			"weakpoint": false}
	var dir := direction.normalized()
	if dir.length_squared() <= 0.0001:
		return {"index": -1, "end": origin, "weakpoint": false}

	var max_dist := max_range
	var wall_end := origin + dir * max_dist
	if is_inside_tree():
		var q := PhysicsRayQueryParameters3D.create(origin, wall_end, 1, exclude)
		q.collide_with_areas = false
		q.collide_with_bodies = true
		var wall_hit := get_world_3d().direct_space_state.intersect_ray(q)
		if not wall_hit.is_empty():
			wall_end = wall_hit.position
			max_dist = origin.distance_to(wall_end)

	var best := -1
	var best_along := max_dist
	var best_weakpoint := false
	for i in range(sim.active):
		var role := enemy_role(i)
		var center := enemy_position(i)
		var radius := 0.58
		match role:
			"ARMORED":
				center.y = 1.05
				radius = 0.95
			"HARASSER":
				radius = 0.72
			_:
				center.y = 0.82
		var to_center := center - origin
		var along := to_center.dot(dir)
		if along <= 0.0 or along >= best_along:
			continue
		var closest := origin + dir * along
		if closest.distance_squared_to(center) > radius * radius:
			continue
		best = i
		best_along = along
		best_weakpoint = false
		if role == "ARMORED":
			var weak_center := center + Vector3.UP * 0.42
			var weak_along := (weak_center - origin).dot(dir)
			var weak_closest := origin + dir * weak_along
			best_weakpoint = weak_along > 0.0 				and weak_closest.distance_squared_to(weak_center) <= 0.34 * 0.34

	if best < 0:
		return {"index": -1, "end": wall_end, "weakpoint": false}
	return {
		"index": best,
		"end": origin + dir * best_along,
		"weakpoint": best_weakpoint,
	}



func find_nearest_role_enemy(world_pos: Vector3, max_range: float,
		role_name_filter: String, require_los: bool = true,
		exclude: Array[RID] = []) -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return -1
	var best := -1
	var best_d2 := max_range * max_range
	for i in range(sim.active):
		if enemy_role(i) != role_name_filter:
			continue
		var p := enemy_position(i)
		var dx := p.x - world_pos.x
		var dz := p.z - world_pos.z
		var d2 := dx * dx + dz * dz
		if d2 >= best_d2:
			continue
		if require_los and not world_los_clear(
				world_pos + Vector3.UP, p + Vector3.UP * 0.25, 1, exclude):
			continue
		best_d2 = d2
		best = i
	return best


func enemy_uid(i: int) -> int:
	if sim_mode and sim != null and i >= 0 and i < sim.active:
		return sim.uid[i]
	if i >= 0 and i < _uid.size():
		return _uid[i]
	return -1


func lane_densities() -> Dictionary:
	var counts := {"A": 0, "B": 0, "C": 0}
	if multiplayer.is_server() and sim_mode and sim != null:
		for i in range(sim.active):
			var li := clampi(int(sim.lane[i]), 0, 2)
			counts[["A", "B", "C"][li]] += 1
	elif not _snaps.is_empty():
		var lanes: PackedByteArray = _snaps[-1].get("lane", PackedByteArray())
		for li_v in lanes:
			var li := clampi(int(li_v), 0, 2)
			counts[["A", "B", "C"][li]] += 1
	# Readability uses absolute per-lane pressure, not share of the current
	# population: 2 enemies on an otherwise empty map must not look like 100%.
	const DENSE_LANE_COUNT := 20.0
	return {
		"A": clampf(float(counts.A) / DENSE_LANE_COUNT, 0.0, 1.0),
		"B": clampf(float(counts.B) / DENSE_LANE_COUNT, 0.0, 1.0),
		"C": clampf(float(counts.C) / DENSE_LANE_COUNT, 0.0, 1.0),
	}


func find_enemy_in_cone(origin: Vector3, forward: Vector3, max_range: float,
		min_dot: float = 0.94) -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return -1
	var best := -1
	var best_d := max_range
	var flat_fwd := Vector3(forward.x, 0.0, forward.z).normalized()
	for i in range(sim.active):
		var to_enemy := enemy_position(i) - origin
		to_enemy.y = 0.0
		var d := to_enemy.length()
		if d > 0.001 and d < best_d and flat_fwd.dot(to_enemy / d) >= min_dot:
			best = i
			best_d = d
	return best


func damage_in_radius(center: Vector3, radius: float, damage: float,
		source_kind: String) -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return 0
	var ids: Array[int] = []
	var r2 := radius * radius
	for i in range(sim.active):
		var p := enemy_position(i)
		var dx := p.x - center.x
		var dz := p.z - center.z
		if dx * dx + dz * dz <= r2:
			ids.append(sim.uid[i])
	var hits := 0
	for target_uid in ids:
		if sim.slot_of_uid(target_uid) >= 0:
			if sim.damage(target_uid, damage, source_kind, false):
				enemy_killed.rpc(target_uid, source_kind)
			hits += 1
	return hits


func find_nearest_enemy(world_pos: Vector3, max_range: float,
		require_unslowed: bool = false, excluded_role: String = "") -> int:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return -1
	var best := -1
	var best_d2 := max_range * max_range
	var half := sim.field.size_m * 0.5
	for i in range(sim.active):
		if require_unslowed and sim.is_slowed_slot(i):
			continue
		if excluded_role != "" and enemy_role(i) == excluded_role:
			continue
		var dx := (sim.px[i] - half) - world_pos.x
		var dz := (sim.pz[i] - half) - world_pos.z
		var d2 := dx * dx + dz * dz
		if d2 < best_d2:
			best_d2 = d2
			best = i
	return best


func apply_slow(i: int, factor: float, duration: float) -> bool:
	if not multiplayer.is_server() or not sim_mode or sim == null:
		return false
	if i < 0 or i >= sim.active:
		return false
	return sim.apply_slow(sim.uid[i], factor, duration)


func enemy_is_slowed(i: int) -> bool:
	return sim_mode and sim != null and sim.is_slowed_slot(i)


func weakpoint_alignment_required(i: int) -> bool:
	return enemy_role(i) == "ARMORED"


func weakpoint_hit(i: int, shooter_pos: Vector3, shooter_forward: Vector3) -> bool:
	if not weakpoint_alignment_required(i):
		return false
	var to_enemy := enemy_position(i) - shooter_pos
	to_enemy.y = 0.0
	if to_enemy.length_squared() <= 0.0001:
		return false
	# Temporary greybox proxy for the lab's glowing weak-point: a much tighter
	# aim cone than a body hit. Replaced by real hit geometry in the visual pass.
	return shooter_forward.normalized().dot(to_enemy.normalized()) >= 0.97


func apply_damage(i: int, dmg: int, shooter: Node, weakpoint: bool = false,
		source_kind: String = "pilot") -> void:
	if not multiplayer.is_server():
		return
	if sim_mode and sim != null:
		if i < 0 or i >= sim.active:
			return
		var target_uid := sim.uid[i]
		if sim.damage(target_uid, float(dmg), source_kind, weakpoint):
			enemy_killed.rpc(target_uid, shooter.name if shooter else "?")
		return
	if _uid.is_empty() or i < 0 or i >= _uid.size():
		return
	_hp[i] = maxf(0.0, _hp[i] - float(dmg))
	if _hp[i] <= 0.0 and _state[i] != EnemySnapshotCodec.ST_DEAD:
		_state[i] = EnemySnapshotCodec.ST_DEAD      # canon value 2
		_respawn_t[i] = 3.0
		_died_uids.append(_uid[i])
		enemy_killed.rpc(_uid[i], shooter.name if shooter else "?")


@rpc("authority", "call_remote", "reliable")
func enemy_killed(uid: int, by: String) -> void:
	if _metrics:
		_metrics.count("enemy_kill_events")
	print("EVENT enemy_killed uid=%d by=%s" % [uid, by])

class_name OperationPresentationAdapter
extends Node

signal snapshot_changed(snap:Dictionary)
signal gameplay_event(ename:StringName,payload:Dictionary)

var runtime:OperationRuntime=null
var crowd:CrowdStream=null
var defense:OperationDefenseRuntime=null
var mech:OperationMechRuntime=null
var players_root:Node3D=null
var _acc:=0.0
var _planned_lanes:Array=[]


func setup(p_runtime:OperationRuntime,p_crowd:CrowdStream,p_defense:OperationDefenseRuntime,
		p_mech:OperationMechRuntime,p_players:Node3D)->void:
	runtime=p_runtime;crowd=p_crowd;defense=p_defense;mech=p_mech;players_root=p_players
	if runtime!=null:
		runtime.mission_event.connect(_on_mission_event)
		runtime.presentation_event.connect(_on_presentation_event)
	push_snapshot()


func _process(delta:float)->void:
	_acc+=delta
	if _acc>=0.2:_acc=0.0;push_snapshot()


func push_snapshot()->void:
	var s:=snapshot()
	if OperationTelemetryContract.validate_snapshot(s).is_empty():snapshot_changed.emit(s)


func snapshot()->Dictionary:
	var state: Dictionary = runtime.get_state() if runtime != null else {}
	var densities: Dictionary = crowd.lane_densities() if crowd != null else {"A":0.0,"B":0.0,"C":0.0}
	var priority: String = ""
	var best: float = 0.0
	for lane in ["A","B","C"]:
		if float(densities.get(lane,0.0))>best:best=float(densities[lane]);priority=lane
	var preview:Dictionary=state.get("threat_preview",{})
	var lanes:Array=preview.get("lanes",[])
	var next_lane:=str(lanes[0]) if not lanes.is_empty() else ""
	var ds: Dictionary = defense.get_state() if defense != null else {}
	var ms: Dictionary = mech.get_state() if mech != null else {}
	var local_peer: int = multiplayer.get_unique_id() if multiplayer.multiplayer_peer != null else 1
	var player: PlayerAvatar = null
	if players_root != null:
		player = players_root.get_node_or_null("Player_%d" % local_peer) as PlayerAvatar
	var mate:PlayerAvatar=null
	if players_root!=null:
		for n in players_root.get_children():
			var p:=n as PlayerAvatar
			if p!=null and p.peer_id!=local_peer:mate=p;break
	var player_state:="on_foot"
	if player!=null:
		if player.downed:player_state="down"
		elif player.embarked:player_state="in_mech"
	var phase_map:={"SCOUT":"deploy","ASSAULT":"combat","INTERMISSION":"interwave",
		"WITHDRAWAL":"combat","CONCLUDED":"ended"}
	var supply:Dictionary=ds.get("supply",{})
	var reserve:=float(supply.get("reserve",0))
	var supply_frac:=0.0
	if not bool(supply.get("destroyed",false)):
		var reserve_frac:=clampf(reserve/800.0,0.0,1.0)
		var hp_frac:=float(supply.get("hp",0.0))/maxf(1.0,float(supply.get("hp_max",1.0)))
		supply_frac=minf(reserve_frac,hp_frac)
	var kpi:Dictionary=state.get("kpis",{})
	# MissionKernel clears the active plan before INTERMISSION, so
	# current_wave_index becomes 0 between waves. Keep the player-facing wave
	# display monotonic by falling back to waves_completed.
	var display_wave:=display_wave_index(state)
	return {
		"t":float(state.get("step",0))*0.1,
		"player_state":player_state,
		"player_hp":float(player.hp)/float(PlayerAvatar.MAX_HP) if player!=null else 1.0,
		"core_hp":float(state.get("core_hp",0))/maxf(1.0,float(state.get("core_max_hp",1))),
		"ex_current":int(state.get("ex_mex",0))/1000,
		"quota":int(state.get("quota_mex",0))/1000,
		"risk_state":str(state.get("risk_id","SAFE")).to_lower(),
		"greedy_pressure":1.0 if str(state.get("risk_id","SAFE"))=="GREEDY" else 0.25,
		"wave":display_wave,
		"waves_total":int(state.get("waves_total",3)),
		"phase":str(phase_map.get(str(state.get("phase","SCOUT")),"deploy")),
		"next_threat_lane":next_lane,"priority_threat_lane":priority,
		"threat_lanes":densities,
		"turret_ammo_state":ds.get("turrets",[]),
		"mech_state":"down" if int(ms.get("actor_state",0))==ActorIface.ActorState.DESTROYED else (
			"active" if int(ms.get("driver_peer",0))>0 else "ready"),
		"mech_integrity":float(ms.get("hp_frac",1.0)),
		"extract_available":bool(state.get("quota_met",false)),
		"extract_window_left":maxf(0.0,float(
			int(state.get("withdrawal_end_step",0))-int(state.get("step",0)))*0.1) \
			if str(state.get("phase",""))=="WITHDRAWAL" else -1.0,
		"supply_state":supply_frac,
		"player_pos":_pos2(player.global_position) if player!=null else Vector2(-999,-999),
		"teammate_pos":_pos2(mate.global_position) if mate!=null else Vector2(-999,-999),
		"mech_pos":_pos2(ms.get("position",Vector3(-999,0,-999))),
		"kpi":kpi,"result":state.get("outcome",{}),
		"active_hazard":str(state.get("active_hazard","")),
		"warning":str(state.get("last_warning","")),
	}


static func display_wave_index(state:Dictionary)->int:
	return maxi(int(state.get("current_wave_index",0)),int(state.get("waves_completed",0)))


static func wave_started_payload(planned_lanes:Array,e:Dictionary)->Dictionary:
	return {
		"lanes":planned_lanes.duplicate(),
		"wave_index":int(e.get("wave_index",0)),
		"name":str(e.get("name","")),
	}


func request_risk(state:StringName)->void:
	if runtime!=null:runtime.request_set_risk(String(state).to_upper())


func request_continue()->void:
	if runtime!=null:runtime.request_start_wave()


func _on_mission_event(e:Dictionary)->void:
	var kind:=str(e.get("kind",""))
	match kind:
		"WAVE_PLANNED":
			var planned_lanes: Array = e.get("lanes", [])
			_planned_lanes=planned_lanes.duplicate()
		"WAVE_STARTED":
			gameplay_event.emit(&"wave_started",wave_started_payload(_planned_lanes,e))
		"CORE_DAMAGED":gameplay_event.emit(&"core_damaged",e)
		"CORE_DESTROYED":gameplay_event.emit(&"core_destroyed",e)
		"RISK_CHANGED":gameplay_event.emit(&"risk_changed",{"state":str(e.get("to","SAFE")).to_lower()})
		"CONTRACT_READY":
			# OperationRuntime already emits the explicit quota_met presentation
			# event for this kernel transition. Do not alias it a second time here.
			pass
		"OPERATION_RESOLVED":
			if str(e.get("outcome",""))=="SUCCESS":
				gameplay_event.emit(&"mission_success",e)
			else:
				gameplay_event.emit(&"mission_failed",e)
	push_snapshot()


func _on_presentation_event(e:Dictionary)->void:
	gameplay_event.emit(StringName(str(e.get("kind","world_event"))),e)
	push_snapshot()


static func _pos2(v:Vector3)->Vector2:return Vector2(v.x,v.z)
